import { lookupOrder } from './order.service';
import { AppError } from '../kernel/errors';

export function refundOrder(orderId: string): AppError | void {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return { code: 'NOT_FOUND', message: `Order ${orderId} not found` };
  }

  if (order.refunded) {
    return { code: 'ALREADY_REFUNDED', message: `Order ${orderId} has already been refunded` };
  }

  if (order.total < 10) {
    return { code: 'INSUFFICIENT_TOTAL', message: `Order ${orderId} total of ${order.total} is below minimum refundable amount of 10` };
  }
}

